/** MHT（MIME multipart）取出 text/html 部分並解碼（quoted-printable／base64，UTF-8） */
function mhtHtml(m){
  if(!/^MIME-Version|Content-Type:\s*multipart/i.test(m.slice(0,500))) return m;
  const part=m.split(/\r?\n--[^\r\n]+/).find(p=>/Content-Type:\s*text\/html/i.test(p)) || m;
  const head=part.slice(0, part.search(/\r?\n\r?\n/)), body=part.replace(/^[\s\S]*?\r?\n\r?\n/,'');
  let bytes;
  if(/Content-Transfer-Encoding:\s*base64/i.test(head)){ const b=atob(body.replace(/\s+/g,'')); bytes=Uint8Array.from(b,c=>c.charCodeAt(0)); }
  else if(/quoted-printable/i.test(head)){
    const qp=body.replace(/=\r?\n/g,''), out=[], enc=new TextEncoder();
    for(let i=0;i<qp.length;i++){ const c=qp[i]; if(c==='=' && /^[0-9A-F]{2}$/i.test(qp.substr(i+1,2))){ out.push(parseInt(qp.substr(i+1,2),16)); i+=2; } else enc.encode(c).forEach(b=>out.push(b)); }
    bytes=new Uint8Array(out);
  } else return body;
  const cs=(head.match(/charset="?([\w-]+)/i)||[])[1]||'utf-8';
  try{ return new TextDecoder(cs).decode(bytes); }catch(e){ return new TextDecoder('utf-8').decode(bytes); }
